<style>
.ecp{--ink:#14374c;--teal:#008e7f;--mint:#e7f6f1;--muted:#6c8696;--line:#d8e6ec;--bg:#f6f9fa;color:var(--ink);font:13px/1.55 Arial,Helvetica,sans-serif;max-width:1460px;margin:0 auto;padding:28px clamp(16px,2.8vw,42px) 56px}
.ecp *{box-sizing:border-box}.ecp :is(h1,h2,h3,p){margin:0}.ecp h1{font-size:34px;letter-spacing:-.04em}.ecp h2{font-size:18px}.ecp h3{font-size:15px}.ecp small,.ecp .sub,.ecp .muted{color:var(--muted)}.ecp small{font-size:11px}.ecp .eyebrow{font-size:10px;font-weight:800;letter-spacing:.09em;color:var(--teal)}
.ecp .head{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:4px 0 20px}.ecp .head p{color:var(--muted);margin:5px 0}.ecp .tabs{display:flex;flex-wrap:wrap;gap:5px;margin:14px 0 22px;padding-bottom:10px;border-bottom:1px solid var(--line)}.ecp .tabs a{border:1px solid transparent;padding:9px 14px;border-radius:8px;color:#56778a;text-decoration:none;font-weight:700}.ecp .tabs a:hover,.ecp .tabs a.active{border-color:#b7e5d7;background:var(--mint);color:#00776b}
.ecp .btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:36px;padding:9px 15px;border:1px solid #c9dee5;border-radius:8px;background:#fff;color:#22516a;text-decoration:none;font:700 12px Arial;cursor:pointer}.ecp .btn:hover{background:#f1faf7}.ecp .btn.primary{background:var(--teal);border-color:var(--teal);color:#fff}.ecp .btn.primary:hover{background:#00796e}.ecp .btn.warn{border-color:#ecc4a5;color:#a3621e;background:#fff8f0}.ecp .btn:disabled{opacity:.45;cursor:not-allowed}.ecp .actions{display:flex;flex-wrap:wrap;gap:9px;align-items:center}
.ecp .card{border:1px solid var(--line);border-radius:12px;background:white;padding:21px;min-width:0}.ecp .grid{display:grid;gap:14px}.ecp .grid.kpis{grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:20px}.ecp .grid.two{grid-template-columns:minmax(0,1.75fr) minmax(275px,1fr)}.ecp .grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}.ecp .kpi label{display:block;color:var(--muted);font-size:12px}.ecp .kpi strong{font-size:30px;display:block;line-height:1.3;margin:6px 0;color:var(--ink)}.ecp .kpi:nth-child(2){background:#eef9f5}.ecp .cardhead{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-bottom:15px}
.ecp .filters{display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto;gap:10px;align-items:end}.ecp label{font-size:12px;font-weight:700;color:#30596d;display:flex;flex-direction:column;gap:6px}.ecp :is(input,select,textarea){font:13px Arial,Helvetica,sans-serif;border:1px solid #cbdde6;border-radius:8px;padding:10px 11px;width:100%;background:#fff;color:#12384c;min-height:37px}.ecp :is(input,select,textarea):focus{outline:2px solid #76cfc0;outline-offset:1px}.ecp textarea{min-height:92px;resize:vertical}.ecp input[type=checkbox]{width:16px;min-height:16px;accent-color:var(--teal)}.ecp input[type=radio]{width:16px;min-height:16px;accent-color:var(--teal)}
.ecp .table-wrap{width:100%;overflow:auto}.ecp table{width:100%;border-collapse:collapse;font-size:12px}.ecp th{background:#eef3f5;color:#526f83;text-align:left;padding:12px}.ecp td{padding:13px 12px;border-bottom:1px solid #e5edf0;vertical-align:middle}.ecp tbody tr:hover{background:#f7fbfa}.ecp td:first-child{font-weight:700}.ecp .tag{display:inline-block;border:1px solid transparent;border-radius:7px;padding:5px 8px;font-size:11px;font-weight:700;background:#eaf1f5;color:#42657b}.ecp .tag.issued,.ecp .tag.accepted{background:#e6f6ed;color:#13715d}.ecp .tag.sent{background:#e7f2fc;color:#2665a1}.ecp .tag.declined,.ecp .tag.generation_failed{background:#ffefeb;color:#b24d37}.ecp .tag.imported{background:#f0edf9;color:#715b9b}.ecp .tag.draft{background:#fff4e4;color:#95601c}.ecp .link{color:#087e73;text-decoration:none;font-weight:700}.ecp .link:hover{text-decoration:underline}
.ecp .formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.ecp .formgrid .full{grid-column:1/-1}.ecp .options{display:flex;flex-wrap:wrap;gap:10px}.ecp .choice{display:flex;flex-direction:row;align-items:center;gap:8px;padding:10px;border:1px solid #d5e5e9;border-radius:8px;flex:1 1 200px}.ecp .choice.disabled{background:#f6f8f9}.ecp .choice small{display:block}.ecp .divider{border-top:1px solid var(--line);margin:17px 0}.ecp .summary{background:#edf8f4;border:1px solid #b9e5d9;border-radius:9px;padding:15px}.ecp .summary strong{font-size:24px;color:#047968}.ecp .summary .line{display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid #d8ede6}.ecp .help{background:#f3f7f9;color:#536f7f;border:1px solid #e0eaef;padding:12px 14px;border-radius:9px}.ecp .warning{background:#fff7e9;border-color:#f1d6ac;color:#92651d}.ecp .success{background:#e9f8f2;border-color:#b8e7d5;color:#0d735f}.ecp .error{background:#fff1f0;border-color:#e8bcb8;color:#9b443c}.ecp .notice{padding:11px 14px;border:1px solid #c8e2dc;border-radius:8px;margin:13px 0}.ecp .list{display:grid;gap:8px}.ecp .listrow{border:1px solid #e1eaee;border-radius:9px;padding:13px;display:flex;gap:10px;align-items:center;justify-content:space-between}.ecp .listrow .sub{font-size:11px}.ecp .amount{font-variant-numeric:tabular-nums}.ecp .pagination{display:flex;align-items:center;gap:5px;justify-content:flex-end;margin-top:18px}.ecp .pagination a,.ecp .pagination span{padding:6px 10px;border-radius:6px;border:1px solid #dde8eb;color:#325c70;text-decoration:none}.ecp .pagination .active{background:var(--teal);color:white}
@media(max-width:970px){.ecp .grid.kpis,.ecp .grid.three{grid-template-columns:repeat(2,minmax(0,1fr))}.ecp .grid.two{grid-template-columns:1fr}.ecp .filters{grid-template-columns:repeat(2,minmax(0,1fr))}.ecp .formgrid{grid-template-columns:1fr}}
@media(max-width:590px){.ecp .grid.kpis,.ecp .grid.three,.ecp .filters{grid-template-columns:1fr}.ecp h1{font-size:28px}.ecp{padding:14px 12px}}
</style>
